// Upstream CSS, line for line, with component-prefixed parts (data-slot),
// keyframes (domino-*) and colors (--domino-*). The row is drawn left to
// right and mirrored as a whole in a right-to-left context. React 19 hoists
// this <style> into <head> once, however many instances render.
const css = `
[data-slot="domino-row"] {
  display: grid;
  column-gap: 20px;
  grid-template-columns: repeat(4, auto);
  place-content: center;
  direction: ltr;
}
[data-slot="domino-row"]:dir(rtl) {
  scale: -1 1;
}
[data-slot="domino-block"] {
  position: relative;
  width: 20px;
  aspect-ratio: 20/60;
  border-radius: 5px;
  transform-origin: right bottom;
}
[data-slot="domino-block"]:nth-child(1) {
  background-color: var(--domino-1, #777);
  animation: domino-fall-down-1 0.65s ease-in-out 0.2s both;
}
[data-slot="domino-block"]:nth-child(2) {
  background-color: var(--domino-2, #bbb);
  animation: domino-fall-down-2 0.65s ease-in-out 0.3s both;
}
[data-slot="domino-block"]:nth-child(3) {
  background-color: var(--domino-3, #aaa);
  animation: domino-fall-down-3 0.65s ease-in-out 0.4s both;
}
[data-slot="domino-block"]:nth-child(4) {
  background-color: var(--domino-4, #999);
  animation: domino-fall-down-4 0.65s ease-in-out 0.5s both;
}
@keyframes domino-fall-down-1 {
  from {
    transform: rotate(0deg);
  }
  60% {
    transform: rotate(60deg);
  }
  80% {
    transform: rotate(55deg);
  }
  to {
    transform: rotate(60deg);
  }
}
@keyframes domino-fall-down-2 {
  from {
    transform: rotate(0deg);
  }
  60% {
    transform: rotate(61deg);
  }
  80% {
    transform: rotate(56deg);
  }
  to {
    transform: rotate(61deg);
  }
}
@keyframes domino-fall-down-3 {
  from {
    transform: rotate(0deg);
  }
  60% {
    transform: rotate(66deg);
  }
  80% {
    transform: rotate(60deg);
  }
  to {
    transform: rotate(66deg);
  }
}
@keyframes domino-fall-down-4 {
  from {
    transform: rotate(0deg);
  }
  60% {
    transform: rotate(90deg);
  }
  80% {
    transform: rotate(85deg);
  }
  to {
    transform: rotate(90deg);
  }
}

/* Reduced motion: no motion; the row shows its fallen end state. */
@media (prefers-reduced-motion: reduce) {
  [data-slot="domino-block"]:nth-child(n) {
    animation: none;
  }
  [data-slot="domino-block"]:nth-child(1) {
    transform: rotate(60deg);
  }
  [data-slot="domino-block"]:nth-child(2) {
    transform: rotate(61deg);
  }
  [data-slot="domino-block"]:nth-child(3) {
    transform: rotate(66deg);
  }
  [data-slot="domino-block"]:nth-child(4) {
    transform: rotate(90deg);
  }
}
`;

/**
 * Four dominoes toppling one after another, once on mount. Remount it
 * (change its `key`) to play it again.
 */
function Domino({ className, ...props }: React.ComponentProps<"div">) {
  const labelled =
    props["aria-label"] !== undefined || props["aria-labelledby"] !== undefined;
  return (
    <div
      data-slot="domino"
      role={labelled ? "img" : undefined}
      aria-hidden={labelled ? undefined : true}
      className={cn(
        "relative grid aspect-square w-full max-w-80 place-content-center overflow-hidden bg-[var(--domino-surface,#fff)]",
        className,
      )}
      {...props}
    >
      <style href="designfrom-domino" precedence="default">
        {css}
      </style>
      <div data-slot="domino-row">
        <div data-slot="domino-block" />
        <div data-slot="domino-block" />
        <div data-slot="domino-block" />
        <div data-slot="domino-block" />
      </div>
    </div>
  );
}

export { Domino };
